def count_pairs(xs, k):
    """
    Returns the number of index pairs (i, j) with i < j and xs[i] + xs[j] == k.
    Raises TypeError if xs is not a list.
    """
    if not isinstance(xs, list):
        raise TypeError("First argument must be a list.")
    if not xs:
        return 0
    count = 0
    n = len(xs)
    for i in range(n):
        for j in range(i + 1, n):
            if xs[i] + xs[j] == k:
                count += 1
    return count
