def count_pairs(xs, k):
    """
    Returns the number of index pairs (i, j) with i < j such that xs[i] + xs[j] == k.
    """
    if not isinstance(xs, list):
        raise TypeError("First argument must be a list.")
    if not xs:
        return 0

    count = 0
    n = len(xs)
    seen = {}
    for i in range(n):
        complement = k - xs[i]
        if complement in seen:
            count += seen[complement]
        if xs[i] in seen:
            seen[xs[i]] += 1
        else:
            seen[xs[i]] = 1
    return count
